import{_ as o,o as r,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"历史回放","description":"","frontmatter":{},"headers":[],"relativePath":"features/playback.md","filePath":"features/playback.md","lastUpdated":null}'),a={name:"features/playback.md"};function d(l,t,e,g,i,u){return r(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="历史回放" tabindex="-1">历史回放 <a class="header-anchor" href="#历史回放" aria-label="Permalink to &quot;历史回放&quot;">​</a></h1><p>历史回放是 Northstar 的核心特色功能：它将指定区间的<strong>历史行情</strong>按设定的节奏重新&quot;播放&quot;出来，就像观看行情录像一样。它是以下场景的共同基础：</p><ul><li><strong>策略回测</strong>：让策略在历史行情中跑一遍，检验策略表现；</li><li><strong>操盘手训练</strong>：在回放行情中手工下单，进行复盘练习（详见 <a href="/features/training">操盘手训练</a>）；</li><li><strong>行情研究</strong>：随时回看任意时间段的市场走势。</li></ul><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>回放在平台中体现为一个特殊的行情网关：</p><ul><li>渠道为 <strong>PLAYBACK</strong>，网关 ID 固定为 <code>PLAYBACK</code>，用途只能是<strong>行情</strong>；</li><li>回放的历史数据来自平台的数据服务；</li><li>回放出的行情与实时行情<strong>完全同构</strong>——K 线图、交易面板、程序化模组都感觉不到差别，因此策略代码无需任何修改即可在历史与实盘间切换。</li></ul><p>回放状态机：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INITIAL（初始） → PRELOADING（预加载中） → PRELOADED（预加载完成） → PLAYING（回放中） → FINISHED（回放结束）</span></span>
<span class="line"><span>                                            ↕ 可跳转时间线        ↕ 可暂停/逐K</span></span></code></pre></div><h2 id="第一步-创建回放网关" tabindex="-1">第一步：创建回放网关 <a class="header-anchor" href="#第一步-创建回放网关" aria-label="Permalink to &quot;第一步：创建回放网关&quot;">​</a></h2><p>进入 <strong>网关管理</strong>（<code>Alt+1</code>），点击右上角 <strong>新建</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写说明</th></tr></thead><tbody><tr><td>网关 ID</td><td>行情网关自动等于渠道名（<code>PLAYBACK</code>），无需修改</td></tr><tr><td>网关描述</td><td>自定义备注</td></tr><tr><td>网关用途</td><td>选择 <strong>行情</strong></td></tr><tr><td>连线方式</td><td>PLAYBACK 渠道不支持自动连线，保持关闭</td></tr><tr><td>网关渠道</td><td>选择 <strong>PLAYBACK</strong></td></tr><tr><td>订阅合约</td><td>多选需要回放的合约（即&quot;回放哪些品种&quot;）</td></tr></tbody></table><p>然后点击弹窗底部的 <strong>网关配置</strong>，设置回放区间与精度：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>预热起始日</strong></td><td>回放正式开始前先加载的历史数据起点，用于让指标&quot;预热&quot;（可选）</td></tr><tr><td><strong>开始日</strong></td><td>回放开始日期（YYYYMMDD，不能早于 2021-01-01）</td></tr><tr><td><strong>结束日</strong></td><td>回放结束日期</td></tr><tr><td><strong>回放精度</strong></td><td>低（每分钟 4 个 TICK）/ 中（每分钟 30 个 TICK）/ 高（每分钟 120 个 TICK）</td></tr></tbody></table><p>弹窗顶部提供 <strong>近一周 / 近三月 / 近一年 / 近两年</strong> 四个快捷按钮，一键填充日期区间。</p><div class="tip custom-block"><p class="custom-block-title">精度如何选择</p><ul><li>看日线/小时线级别的复盘，选<strong>低</strong>精度即可，加载最快；</li><li>需要在分钟级观察盘口节奏，选<strong>中</strong>；</li><li>tick 级精细回测选<strong>高</strong>，但数据量与加载时间会显著增加。</li></ul></div><h2 id="第二步-打开回放控制面板" tabindex="-1">第二步：打开回放控制面板 <a class="header-anchor" href="#第二步-打开回放控制面板" aria-label="Permalink to &quot;第二步：打开回放控制面板&quot;">​</a></h2><p>有两种方式打开<strong>历史回放控制面板</strong>（非模态窗口，可拖动）：</p><ol><li><strong>网关管理</strong> → 找到 PLAYBACK 网关卡片 → 右上角&quot;更多&quot;下拉 → <strong>回放</strong>；</li><li><strong>多图同列</strong>页面 → 数据类型选&quot;回放&quot; → 头部回放控制区点&quot;更多&quot;图标。</li></ol><p>控制面板各控件说明：</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td><strong>当前时间线</strong></td><td>显示回放当前时间；仅在&quot;预加载完成&quot;状态下可编辑，改时间即<strong>跳转</strong>到该时间点</td></tr><tr><td><strong>数据预加载</strong> ⏩</td><td>加载回放区间的数据（仅初始状态可用），快捷键 <code>Alt+Q</code></td></tr><tr><td><strong>开始回放</strong> ▶</td><td>预加载完成后启动回放，快捷键 <code>Alt+Q</code></td></tr><tr><td><strong>暂停回放</strong> ⏸</td><td>暂停，快捷键 <code>Alt+Q</code></td></tr><tr><td><strong>逐K回放</strong> ⏭</td><td>每按一次向前推进一根K线，快捷键 <code>Alt+W</code></td></tr><tr><td><strong>状态重置</strong> 🔄</td><td>回到初始状态（同时重置所有回测模组），快捷键 <code>Alt+S</code></td></tr><tr><td><strong>回放速度</strong></td><td>滑块无级调速，提示&quot;每TICK间隔 n 毫秒&quot;，范围从&quot;正常&quot;到&quot;极速&quot;</td></tr><tr><td><strong>逐K步长</strong></td><td>逐K回放时每次推进的K线周期：1m / 3m / 5m / 10m / 15m / 30m / 1h / 2h / 4h</td></tr></tbody></table><h2 id="第三步-观看回放行情" tabindex="-1">第三步：观看回放行情 <a class="header-anchor" href="#第三步-观看回放行情" aria-label="Permalink to &quot;第三步：观看回放行情&quot;">​</a></h2><p>进入 <strong>交易中心 → 多图同列</strong>（<code>Alt+9</code>）：</p><ol><li>头部 <strong>数据类型</strong> 选择 <strong>回放</strong>；</li><li>选择 <strong>图表数</strong>（1/2/3/4/5/6/9/12 宫格）、<strong>周期</strong>（可多选，1m ~ 1d/1wk）、<strong>品种</strong>（可多选）；</li><li>点击 <strong>刷新</strong>，图表会加载回放时间线之前的历史K线；</li><li>用头部内联的回放按钮（预加载/播放/暂停/逐K/更多）或快捷键控制回放，行情便会在图表上&quot;活&quot;起来。</li></ol><p>图表还支持：</p><ul><li><strong>右键菜单</strong>：切换品种、指标参数设置、全屏、截图；</li><li><strong>画线工具</strong>：直线、水平线、斐波那契、三浪五浪等技术分析画线；</li><li><strong>画线交易</strong>：在图上画出多头/空头/止盈/止损/交易计划（需先在交易面板指定交易账户）；</li><li><strong>图表通用设定</strong>（头部&quot;设置&quot;按钮）：红涨绿跌/绿涨红跌、历史持仓线、主图/副图指标。</li></ul><h2 id="第四步-查看回放结果" tabindex="-1">第四步：查看回放结果 <a class="header-anchor" href="#第四步-查看回放结果" aria-label="Permalink to &quot;第四步：查看回放结果&quot;">​</a></h2><ul><li><strong>程序化回测</strong>：用途为&quot;回测&quot;的模组，在 <strong>模组管理 → 运行时状态</strong> 查看实时绩效（余额、盈亏、胜率、最大回撤等），详见 <a href="/features/auto-trading">程序化交易</a>；</li><li><strong>手工交易复盘</strong>：在交易面板点&quot;账户绩效&quot;图标，查看交易记录、交易统计与盈亏曲线；</li><li><strong>批量回测</strong>：使用 <strong>策略探索</strong> 页面对&quot;一个策略 × 多个合约&quot;批量跑回测并生成回测报告，详见 <a href="/features/auto-trading#策略探索-批量回测">策略探索</a>。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意</p><p><strong>状态重置</strong>会同时重置所有用途为&quot;回测&quot;的模组（清空其账户与持仓）。如果回测模组正在跑出满意的结果，先记录绩效再重置。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：预加载很慢？</strong> 回放区间越长、精度越高、订阅合约越多，预加载越慢。建议先用&quot;近一周&quot;+ 低精度熟悉流程。</p><p><strong>Q：回放途中想跳到某个时点？</strong> 暂停后，等状态回到&quot;预加载完成&quot;即可直接修改&quot;当前时间线&quot;进行跳转。</p><p><strong>Q：回放与&quot;策略探索&quot;的回测有什么区别？</strong> 回放是&quot;可视化、可交互&quot;的，行情逐TICK播放，可以中途暂停、手工下单；策略探索是&quot;静默批量&quot;的，跑完直接出报告，适合参数寻优。</p>`,32)])])}const p=o(a,[["render",d]]);export{h as __pageData,p as default};
